<?php
namespace App\Http\Controllers;use App\Models\{Floor,Insight,Institution};use Illuminate\Contracts\View\View;use Illuminate\Http\Request;
class DashboardController extends Controller{public function index(Request $r):View{$floors=Floor::with(['building','activeFloorPlan'])->withCount('surveys')->orderBy('name')->get();return view('dashboard',['pageTitle'=>'SignalGrid Network Intelligence','isDemonstration'=>false,'lastUpdatedAt'=>now(),'displayName'=>$r->user()->name,'displayRole'=>$r->user()->getRoleNames()->first()??'Viewer','institutionName'=>Institution::query()->orderBy('id')->value('name') ?: 'Adekunle Ajasin University, Akungba','analyticsFloors'=>$floors,'dashboardInsights'=>Insight::with('floor.building')->latest('generated_at')->limit(3)->get()]);}}
